#!/usr/bin/env python3

# Make-overview.py
#
# Utility script to generate the Overview page based on the markdown overview
# in the git repo
# (see <https://github.com/cldf-datasets/cldf_meta/blob/master/docs/overview.md>)

from collections import namedtuple
import pathlib
import re
import string
import sys
import unicodedata

from markdown import markdown

MAKO_TEMPLATE = """<%inherit file="home_comp.mako"/>
<%block name="title">Overview</%block>

## This file was automatically generated using `Make-overview.py`.
## Do not edit this file by hand.

<%def name="sidebar()">
  <div class="well toc">
    <h3>Contents</h3>
    <ol class="nested">
$TOC
    </ol>
  </div>
</%def>

$PAGE_CONTENT
"""

Section = namedtuple('Section', 'id caption subsections')


def slug(s):
    return ''.join(
        '-' if c.isspace() else c
        for c in unicodedata.normalize('NFKD', s).lower()
        if c in 'abcdefghijklmnopqrstuvwxyz0123456789 -_')


def html_from_section(section):
    link = f'<a href="#{section.id}">{section.caption}</a>'
    if section.subsections:
        subsections = '\n'.join(map(html_from_section, section.subsections))
        return f'<li>\n{link}\n<ol class="nested">\n{subsections}\n</ol>\n</li>'
    else:
        return f'<li>{link}</li>'


class LinkCollector:
    def __init__(self):
        self.links = {}

    def collect_links(self, lines):
        for line in lines:
            if (m := re.fullmatch(r'\[([-a-zA-Z0-9_]+)\]:\s+(.*)', line)):
                label, link = m.groups()
                assert label not in self.links
                self.links[label] = link
            else:
                yield line

    def link_from_label(self, re_match):
        text, label = re_match.groups()
        text = text.replace(r'\_', '_')
        text = re.sub(
            '^../', 'https://github.com/cldf-datasets/cldf_meta/blob/master/',
            text)
        target = self.links[label]
        target = re.sub(
            '^../', 'https://github.com/cldf-datasets/cldf_meta/blob/master/',
            target)
        return f'${{h.external_link({repr(target)}, label={repr(text)})}}'

    def link_from_inline(self, re_match):
        text, target = re_match.groups()
        text = text.replace(r'\_', '_')
        text = re.sub(
            '^../', 'https://github.com/cldf-datasets/cldf_meta/blob/master/',
            text)
        target = re.sub(
            '^../', 'https://github.com/cldf-datasets/cldf_meta/blob/master/',
            target)
        return f'${{h.external_link({repr(target)}, label={repr(text)})}}'

    def replace_links(self, line):
        line = re.sub(
            r'\[([^\]]+)\]\[([-a-zA-Z0-9_]+)\]',
            self.link_from_label, line)
        line = re.sub(
            r'\[([^\]]+)\]\(([-a-zA-Z0-9_]+)\)',
            self.link_from_inline, line)
        return line


class TocCollector:
    def __init__(self):
        self.title =  ''
        self.toc = []
        self.ids = {}

    def make_id(self, caption):
        candidate = slug(caption)
        count = self.ids.get(candidate) or 0
        id_ = f'{candidate}-{count + 1}' if count > 0 else candidate
        self.ids[candidate] = count + 1
        return id_

    def process_section_captions(self, line):
        if line.startswith('# '):
            self.title = line.lstrip('# ')
            return f'#{line}'
        elif line.startswith('## '):
            caption = line.lstrip('# ')
            section = Section(
                id=self.make_id(caption),
                caption=caption,
                subsections=[])
            self.toc.append(section)
            return f'<h3 id="{section.id}">{section.caption}</h3>'
        elif line.startswith('### '):
            caption = line.lstrip('# ')
            section = Section(
                id=self.make_id(caption),
                caption=caption,
                subsections=[])
            self.toc[-1].subsections.append(section)
            return f'<h4 id="{section.id}">{section.caption}</h4>'
        elif line.startswith('#### '):
            caption = line.lstrip('# ')
            section = Section(
                id=self.make_id(caption),
                caption=caption,
                subsections=[])
            self.toc[-1].subsections[-1].subsections.append(section)
            return f'<h5 id="{section.id}">{section.caption}</h5>'
        else:
            return line


def main():
    if len(sys.argv) != 2:
        print('usage:', sys.argv[0], 'cldf-metadata', file=sys.stderr)
        sys.exit(64)

    cldf_md = sys.argv[1]

    overview_md = pathlib.Path(cldf_md).parent.parent / 'docs' / 'overview.md'
    with open(overview_md, encoding='utf-8') as f:
        overview_text = f.read()

    overview_text = re.sub(r'<!--.*?-->', '', overview_text, flags=re.DOTALL)
    overview_lines = overview_text.splitlines()

    link_collector = LinkCollector()
    overview_lines = list(link_collector.collect_links(overview_lines))
    overview_lines = list(map(link_collector.replace_links, overview_lines))

    toc_collector = TocCollector()
    overview_lines = list(map(
        toc_collector.process_section_captions,
        overview_lines))

    template = string.Template(MAKO_TEMPLATE)
    mako_content = template.substitute(
        TOC='\n'.join(map(html_from_section, toc_collector.toc)),
        PAGE_CONTENT=markdown('\n'.join(overview_lines)))
    with open('cldf_meta/templates/overview.mako', 'w', encoding='utf-8') as f:
        print(mako_content, file=f)


if __name__ == '__main__':
    main()
